// next local day (after 07:00 JST = 22:00Z) the cap resets
assert.equal(r(g, tokyo, '2026-03-11T22:00:00Z').allowed, true);

// Cap is by local midnight, not rolling 24h: NY user, quiet 01:00-02:00
const ny = { id: 'n', timeZone: 'America/New_York', quietStart: '01:00', quietEnd: '02:00', dailyCap: 1 };
g = createPushGate();
assert.equal(r(g, ny, '2026-03-11T03:30:00Z').allowed, true);  // 23:30 EDT Mar 10 (DST started Mar 8)
assert.equal(r(g, ny, '2026-03-11T04:10:00Z').allowed, true);  // 00:10 EDT Mar 11, new day
assert.equal(r(g, ny, '2026-03-11T05:00:00Z').reason, 'daily_cap_reached');

// Same UTC instant, different users/zones are independent
g = createPushGate();
const a = { ...tokyo, id: 'a', dailyCap: 1 }, b = { ...tokyo, id: 'b', dailyCap: 1 };
assert.equal(r(g, a, '2026-03-10T03:00:00Z').allowed, true);
assert.equal(r(g, b, '2026-03-10T03:00:00Z').allowed, true);
assert.equal(r(g, a, '2026-03-10T04:00:00Z').reason, 'daily_cap_reached');
assert.equal(r(createPushGate(), a, '2026-03-10T04:00:00Z').allowed, true); // independent gate

// Settings taken from each call
g = createPushGate();
assert.equal(r(g, { ...a, dailyCap: 2 }, '2026-03-10T03:00:00Z').allowed, true);
assert.equal(r(g, { ...a, dailyCap: 1 }, '2026-03-10T04:00:00Z').reason, 'daily_cap_reached');
assert.equal(r(g, { ...a, dailyCap: 2 }, '2026-03-10T04:00:00Z').allowed, true);

// Non-wrapping quiet window and cap 0
const day = { id: 'd', timeZone: 'UTC', quietStart: '13:00', quietEnd: '15:00', dailyCap: 0 };
assert.equal(r(createPushGate(), day, '2026-03-10T14:00:00Z').reason, 'quiet_hours');
assert.equal(r(createPushGate(), day, '2026-03-10T10:00:00Z').reason, 'daily_cap_reached');

// Invalid input fails closed with distinct codes
g = createPushGate();
for (const [u, code] of [[{ ...a, timeZone: 'Nope/Zone' }, 'invalid_time_zone'], [{ ...a, quietStart: '25:00' }, 'invalid_quiet_hours'], [{ ...a, dailyCap: 1.5 }, 'invalid_daily_cap'], [null, 'invalid_user']])
  assert.equal(r(g, u, '2026-03-10T03:00:00Z').reason, code);
assert.equal(g.attempt(a, new Date('x')).reason, 'invalid_time');
console.log('all ok');
